import {browserStore,DEFAULT,resultOf} from './store.mjs';
const $=id=>document.getElementById(id),store=browserStore();
const money=x=>'$'+x.toFixed(2),date=x=>new Date(x).toLocaleString('en-GB',{timeZone:'UTC'})+' UTC';
function status(text){$('workspace-status').textContent=text;window.dispatchEvent(new Event('battery-render'));}
function button(text,action){const b=document.createElement('button');b.className='text-button';b.type='button';b.textContent=text;b.addEventListener('click',action);return b;}
function link(text,href){const a=document.createElement('a');a.className='text-button';a.textContent=text;a.href=href;return a;}
function text(tag,value,cls){const el=document.createElement(tag);el.textContent=value;if(cls)el.className=cls;return el;}
function download(name,value){const url=URL.createObjectURL(new Blob([value],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function render(){try{const data=store.read();if($('policy-list')){const list=$('policy-list');list.replaceChildren();for(const p of data.policies){const row=document.createElement('article');row.className='record';row.append(text('h2',p.name),text('p',`Reserve ${money(p.scenario.reserve)} / protected ${money(p.scenario.floor)} / task ${money(p.scenario.rate)}`),text('p',`Updated ${date(p.updatedAt)}`,'fine'));const actions=document.createElement('div');actions.className='actions';actions.append(link('[ OPEN POLICY ]','/lab?policy='+p.id),button('[ EXPORT POLICY ]',()=>download('battery-policy.json',JSON.stringify({schema:'battery.workspace/1',policies:[p],runs:[]},null,2))),button('[ REMOVE ]',()=>{try{store.removePolicy(p.id);render();status('Policy removed. Saved test receipts are retained.');}catch(e){status(e.message);}}));row.append(actions);list.append(row);}if(!data.policies.length)list.append(text('p','No policies saved in this browser yet. Start with a preset below.','empty'));}
 if($('run-list')){const id=new URLSearchParams(location.search).get('id'),list=$('run-list');list.replaceChildren();const rows=id?data.runs.filter(r=>r.id===id):data.runs;for(const r of rows){const result=resultOf(r),row=document.createElement('article');row.className='record';row.append(text('p',`[ SIMULATION / ${date(r.createdAt)} ]`,'fine'),text('h2',r.name),text('p',`[ ${result.stopped===null?'SURVIVED':'PAUSED SAFELY'} ] ${result.hours}/72 hours / ${money(result.balance)} remaining`));const details=document.createElement('details');details.open=Boolean(id);details.append(text('summary','Policy and execution receipt'));const pre=document.createElement('pre');pre.className='code';pre.textContent=JSON.stringify({schema:'battery.simulation-receipt/1',id:r.id,engine:r.engine,kind:r.kind,createdAt:r.createdAt,policy:r.scenario,result:{hours:result.hours,balance:result.balance,protected:result.protected,events:result.events}},null,2);details.append(text('p','Recomputed from the saved policy using engine v1. This is an illustrative result, not a provider receipt.','fine'),pre);row.append(details);const actions=document.createElement('div');actions.className='actions';actions.append(link('[ RE-RUN ]','/lab#'+new URLSearchParams({test:JSON.stringify(r.scenario)})),link('[ OPEN RECEIPT ]','/runs?id='+r.id),button('[ EXPORT TEST ]',()=>download('battery-test.json',JSON.stringify({schema:'battery.workspace/1',policies:[],runs:[r]},null,2))));row.append(actions);list.append(row);}if(!rows.length)list.append(text('p',id?'Receipt not found in this browser. Shared links contain the policy only; saved history stays on the device that created it.':'No recorded tests yet. Run a blackout, then record its result.','empty'));}
 window.dispatchEvent(new Event('battery-render'));}catch(e){status(e.message+' Existing data has not been overwritten.');}}
$('export-workspace')?.addEventListener('click',()=>{try{download('battery-workspace.json',store.export());status('Workspace exported. Keep this file to move it to another browser.');}catch(e){status(e.message);}});
$('import-workspace')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>250000)throw Error('Import must be below 250 KB.');const result=store.import(await file.text());render();status(`Import complete: ${result.policies} policies / ${result.runs} tests in file. Duplicate IDs were retained unchanged.`);}catch(error){status('Import rejected: '+error.message);}finally{e.target.value='';}});
window.addEventListener('storage',render);render();
